     6	#include "openexr_compression.h"
     7	#include "openexr_base.h"
     8	#include "internal_memory.h"
     9	#include "internal_structs.h"
    10	
    11	#include <libdeflate.h>
    12	
    13	#if (                                                                          \
    14	    LIBDEFLATE_VERSION_MAJOR > 1 ||                                            \
    15	    (LIBDEFLATE_VERSION_MAJOR == 1 && LIBDEFLATE_VERSION_MINOR > 18))
    16	#    define EXR_USE_CONFIG_DEFLATE_STRUCT 1
    17	#endif
    18	
    19	/* value Aras found to be better trade off of speed vs size */
    20	#define EXR_DEFAULT_ZLIB_COMPRESS_LEVEL 4
    21	
    22	/**************************************/
    23	
    24	size_t
    25	exr_compress_max_buffer_size (size_t in_bytes)
    26	{
    27	    size_t r, extra;
    28	
    29	    r = libdeflate_zlib_compress_bound (NULL, in_bytes);
    30	    /*
    31	     * lib deflate has a message about needing a 9 byte boundary
    32	     * but is unclear if it actually adds that or not
    33	     * (see the comment on libdeflate_deflate_compress)
    34	     */
    35	    if (r > (SIZE_MAX - 9)) return (size_t) (SIZE_MAX);
    36	    r += 9;
    37	
    38	    /*
    39	     * old library had uiAdd( uiAdd( in, ceil(in * 0.01) ), 100 )
    40	     */
    41	    extra = (in_bytes * (size_t) 130);
    42	    if (extra < in_bytes) return (size_t) (SIZE_MAX);
    43	    extra /= (size_t) 128;
    44	
    45	    if (extra > (SIZE_MAX - 100)) return (size_t) (SIZE_MAX);
    46	
    47	    if (extra > r) r = extra;
    48	    return r;
    49	}
    50	
    51	/**************************************/
    52	
    53	exr_result_t
    54	exr_compress_buffer (
    55	    exr_const_context_t ctxt,
    56	    int                 level,
    57	    const void*         in,
    58	    size_t              in_bytes,
    59	    void*               out,
    60	    size_t              out_bytes_avail,
    61	    size_t*             actual_out)
    62	{
    63	    struct libdeflate_compressor*       comp;
    64	    const struct _internal_exr_context* pctxt = EXR_CCTXT (ctxt);
    65	#ifdef EXR_USE_CONFIG_DEFLATE_STRUCT
    66	    struct libdeflate_options opt = {
    67	        .sizeof_options = sizeof (struct libdeflate_options),
    68	        .malloc_func    = pctxt ? pctxt->alloc_fn : internal_exr_alloc,
    69	        .free_func      = pctxt ? pctxt->free_fn : internal_exr_free};
    70	
    71	#else
    72	    libdeflate_set_memory_allocator (
    73	        pctxt ? pctxt->alloc_fn : internal_exr_alloc,
    74	        pctxt ? pctxt->free_fn : internal_exr_free);
    75	#endif
    76	
    77	    if (level < 0)
    78	    {
    79	        exr_get_default_zip_compression_level (&level);
    80	        /* truly unset anywhere */
    81	        if (level < 0) level = EXR_DEFAULT_ZLIB_COMPRESS_LEVEL;
    82	    }
    83	
    84	#ifdef EXR_USE_CONFIG_DEFLATE_STRUCT
    85	    comp = libdeflate_alloc_compressor_ex (level, &opt);
    86	#else
    87	    comp = libdeflate_alloc_compressor (level);
    88	#endif
    89	    if (comp)
    90	    {
    91	        size_t outsz;
    92	        outsz =
    93	            libdeflate_zlib_compress (comp, in, in_bytes, out, out_bytes_avail);
    94	
    95	        libdeflate_free_compressor (comp);
    96	
    97	        if (outsz != 0)
    98	        {
    99	            if (actual_out) *actual_out = outsz;
   100	            return EXR_ERR_SUCCESS;
   101	        }
   102	        return EXR_ERR_OUT_OF_MEMORY;
   103	    }
   104	    return EXR_ERR_OUT_OF_MEMORY;
   105	}
   106	
   107	/**************************************/
   108	
   109	exr_result_t
   110	exr_uncompress_buffer (
   111	    exr_const_context_t ctxt,
   112	    const void*         in,
   113	    size_t              in_bytes,
   114	    void*               out,
   115	    size_t              out_bytes_avail,
   116	    size_t*             actual_out)
   117	{
   118	    struct libdeflate_decompressor*     decomp;
   119	    enum libdeflate_result              res;
   120	    size_t                              actual_in_bytes;
   121	    const struct _internal_exr_context* pctxt = EXR_CCTXT (ctxt);
   122	#ifdef EXR_USE_CONFIG_DEFLATE_STRUCT
   123	    struct libdeflate_options opt = {
   124	        .sizeof_options = sizeof (struct libdeflate_options),
   125	        .malloc_func    = pctxt ? pctxt->alloc_fn : internal_exr_alloc,
   126	        .free_func      = pctxt ? pctxt->free_fn : internal_exr_free};
   127	
   128	    decomp = libdeflate_alloc_decompressor_ex (&opt);
   129	#else
   130	    libdeflate_set_memory_allocator (
   131	        pctxt ? pctxt->alloc_fn : internal_exr_alloc,
   132	        pctxt ? pctxt->free_fn : internal_exr_free);
   133	    decomp = libdeflate_alloc_decompressor ();
   134	#endif
   135	
   136	    if (decomp)
   137	    {
   138	        res = libdeflate_zlib_decompress_ex (
   139	            decomp,
   140	            in,
   141	            in_bytes,
   142	            out,
   143	            out_bytes_avail,
   144	            &actual_in_bytes,
   145	            actual_out);
   146	
   147	        libdeflate_free_decompressor (decomp);
   148	
   149	        if (res == LIBDEFLATE_SUCCESS)
   150	        {
   151	            if (in_bytes == actual_in_bytes) return EXR_ERR_SUCCESS;
   152	            /* it's an error to not consume the full buffer, right? */
   153	        }
   154	        return EXR_ERR_CORRUPT_CHUNK;
   155	    }
   156	    return EXR_ERR_OUT_OF_MEMORY;
   157	}
